        {%- endset -%}
        {{ include('compose/Inline.html.twig', {'class': 'text-sm font-semibold', 'children': c_1}, with_context = false) }}
        {%- set c_2 -%}
          {{ og_text(og_get(v_p, ['text'])) }}
        {%- endset -%}
        {{ include('compose/Inline.html.twig', {'class': 'text-xs text-muted-foreground', 'children': c_2}, with_context = false) }}
      {%- endset -%}
      {{ include('compose/Inline.html.twig', {'class': 'flex flex-col items-start justify-start gap-0', 'children': c_3}, with_context = false) }}
    {%- endset -%}
    {{ include('compose/Label.html.twig', {'class': 'flex items-center gap-4 rounded p-4 inset-ring inset-ring-border has-checked:inset-ring-foreground', 'attrs': og_attrs(['data-testid', 'payment']), 'children': c_4}, with_context = false) }}
  {%- endfor %}
{%- endset -%}
{{ include('compose/Grid.html.twig', {'cols': '1-2', 'class': 'gap-4', 'attrs': og_attrs(['data-testid', 'payments']), 'children': c_5}, with_context = false) }}
